const webhookData = $('Webhook analisis-competidores').item.json.body;
const empresasRows = $('Postgres - Obtener empresas seleccionadas').all().map(r => r.json);
const faseDataRows = $('Postgres - Obtener analisis pliego definitivo').all();
const faseData = faseDataRows.length > 0 ? faseDataRows[0].json : {};
const documentosBase64 = webhookData.documentosBase64 || [];

const porEmpresa = faseData.analisis_claude?.por_empresa || {};

const empresasCtx = empresasRows.map(e => {
  const analisisEmpresa = porEmpresa[e.empresa_id];
  return 'Empresa ID: ' + e.empresa_id + ' | Nombre: ' + e.empresa_nombre + (analisisEmpresa ? ' | Veredicto previo: ' + (analisisEmpresa.veredicto_final || 'N/A') : '');
}).join('\n');

const systemPrompt = 'Eres un experto juridico en contratacion publica colombiana. Analiza el informe de evaluacion y las observaciones de los oferentes. Devuelve UNICAMENTE un JSON valido (sin markdown): {"resumen_general":"string","ranking_competidores":[{"nombre_proponente":"string","puntaje_habilitante":"habilitado|no_habilitado","puntaje_ponderacion":0,"observaciones_detectadas":"string"}],"por_empresa":{"<empresaId>":{"puntaje_ponderacion":0,"ranking":0,"oportunidades_observacion":[{"tipo":"puntaje_propio_subvalorado|puntaje_competidor_cuestionable","descripcion":"string","argumento":"string"}],"estrategia_texto":"string"}}}';

const userText = 'LICITACION ID: ' + webhookData.licitacionId + '\n\nEMPRESAS PROPIAS INVOLUCRADAS:\n' + (empresasCtx || 'Ninguna seleccionada') + '\n\nA continuacion el informe de evaluacion y observaciones de otros oferentes.';

const contentBlocks = [{ type: 'text', text: userText }];
for (const doc of documentosBase64) {
  contentBlocks.push({
    type: 'document',
    source: { type: 'base64', media_type: doc.mediaType, data: doc.base64 },
    title: doc.nombre
  });
}
if (documentosBase64.length === 0) {
  contentBlocks.push({ type: 'text', text: 'Sin documentos adjuntos.' });
}

const requestBody = {
  model: 'claude-sonnet-4-6',
  max_tokens: 8192,
  system: systemPrompt,
  messages: [{ role: 'user', content: contentBlocks }]
};

return [{ json: { faseId: webhookData.faseId, claudeBody: JSON.stringify(requestBody) } }];

const response = $('Claude API - Analisis competidores').item.json;
const buildData = $('Code - Build Claude Request').item.json;

let rawText = '';
if (response.content && response.content[0] && response.content[0].text) {
  rawText = response.content[0].text.trim().replace(/```json/g, '').replace(/```/g, '').trim();
}

let parsed = null;
try { parsed = JSON.parse(rawText); }
catch(e) { parsed = { error: 'respuesta_no_valida', raw: rawText.substring(0, 500) }; }

// Separar general y por_empresa para merge individual
const generalData = { resumen_general: parsed.resumen_general, ranking_competidores: parsed.ranking_competidores };
const porEmpresa = parsed.por_empresa || {};

return [{ json: {
  faseId: buildData.faseId,
  generalData: JSON.stringify(generalData),
  porEmpresa: JSON.stringify(porEmpresa)
} }];
